window.S17Page={"sceneId":"r1","caseId":"s17x-r1-distillation-optimization","name":"常减压装置操作优化","title":"常减压操作优化：收率、质量与能耗的边界","summary":"同一原油批次，为什么不能只把炉温调高？先读懂分馏与质量约束，再用实际拟合的代理模型寻找可行操作点。","directory":"expansion-cases","caseVersion":"1.0.0","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){'use strict';
const mean=a=>a.reduce((s,v)=>s+v,0)/a.length;
function solve(A,b){let m=A.map((r,i)=>r.slice().concat(b[i]));for(let k=0;k<b.length;k++){let q=k;for(let i=k+1;i<b.length;i++)if(Math.abs(m[i][k])>Math.abs(m[q][k]))q=i;[m[q],m[k]]=[m[k],m[q]];let z=m[k][k];for(let j=k;j<=b.length;j++)m[k][j]/=z;for(let i=0;i<b.length;i++)if(i!==k){let d=m[i][k];for(let j=k;j<=b.length;j++)m[i][j]-=d*m[k][j];}}return m.map(r=>r[b.length]);}
const features=x=>{let t=(x.temperature-365)/15,r=(x.reflux-2)/.6,p=(x.pressure-8)/3;return[1,t,r,p,t*t,r*r,t*r];};
function fit(rows){let n=7,A=Array.from({length:n},()=>Array(n).fill(0)),B=Array.from({length:3},()=>Array(n).fill(0));rows.forEach(r=>{let z=features(r.x);for(let j=0;j<n;j++){for(let k=0;k<n;k++)A[j][k]+=z[j]*z[k];r.y.forEach((y,h)=>B[h][j]+=z[j]*y);}});for(let j=1;j<n;j++)A[j][j]+=.0001;return B.map(b=>solve(A,b));}
function predict(model,x){let z=features(x);return model.map(c=>c.reduce((s,v,i)=>s+v*z[i],0));}
function generate(){let rows=[];for(let i=0;i<160;i++){let t=((i*37)%157)/156*2-1,r=((i*67+17)%157)/156*2-1,p=((i*97+33)%157)/156*2-1,x={temperature:365+15*t,reflux:2+.6*r,pressure:8+3*p},noise=Math.sin(i*2.07);rows.push({id:'CDU-'+String(i+1).padStart(3,'0'),x,y:[66+5*t+3*r-2*t*t-r*r+.6*t*r-2*p+.13*noise,1.6+.14*t+.22*r+.05*t*t+.04*r*r-.12*p+.005*Math.cos(i),342+5*t-6*r+2*p+.15*noise],split:i<112?'train':'test'});}return rows;}
function evaluate(model,test){return ['总馏分回收率','单位能耗','柴油终馏点'].map((name,j)=>({name,n:test.length,mae:mean(test.map(r=>Math.abs(predict(model,r.x)[j]-r.y[j])))}));}
function run(params={}){let cfg={pressure:8,energyLimit:1.85,endpointLimit:348,...params},data=generate(),train=data.filter(r=>r.split==='train'),test=data.filter(r=>r.split==='test'),model=fit(train),grid=[];for(let t=350;t<=380;t+=1)for(let ri=0;ri<=30;ri++){let x={temperature:t,reflux:1.4+ri*.04,pressure:+cfg.pressure},y=predict(model,x);grid.push({x,y,feasible:y[1]<=+cfg.energyLimit&&y[2]<=+cfg.endpointLimit});}let feasible=grid.filter(c=>c.feasible).sort((a,b)=>b.y[0]-a.y[0]),baseline={x:{temperature:365,reflux:2,pressure:+cfg.pressure}};baseline.y=predict(model,baseline.x);baseline.feasible=baseline.y[1]<=+cfg.energyLimit&&baseline.y[2]<=+cfg.endpointLimit;let chosen=feasible[0]||null,means=[0,1,2].map(j=>mean(train.map(r=>r.y[j])));return{sceneId:'r1',params:cfg,dataNature:'固定种子教学合成工况；非现场标定',split:{train:112,test:48,unit:'独立工况批次'},model,grid,feasibleCount:feasible.length,chosen,baseline,metrics:evaluate(model,test),baselineMetrics:means.map((v,j)=>({n:test.length,mae:mean(test.map(r=>Math.abs(v-r.y[j])))})),test:test.map(r=>({id:r.id,x:r.x,prediction:predict(model,r.x),truth:r.y})),improvement:chosen?chosen.y[0]-baseline.y[0]:null};}
g.R1Core={features,fit,predict,generate,evaluate,run};})(globalThis);

